<div class="board">@foreach($columns as $status=>$leads)<section class="board-column" data-status="{{$status}}"><div class="column-head"><span>{{$status}}</span><span class="column-count">{{$leads->count()}}</span></div><div class="card-list" data-status="{{$status}}">@foreach($leads as $lead)<article class="lead-card" data-id="{{$lead->id}}"><div class="d-flex justify-content-between gap-2"><div><h3>{{$lead->business_name}}</h3><div class="meta">{{$lead->business_category}} · {{$lead->city}}</div></div><strong class="text-success">{{$lead->lead_score}}</strong></div><div class="card-badges"><span class="badge quality-{{$lead->lead_quality}}">{{$lead->lead_quality}}</span>@unless($lead->has_website)<span class="badge bg-danger-subtle text-danger">No website</span>@endunless @if($lead->phone)<span class="badge bg-info-subtle text-info-emphasis">Has phone</span>@endif</div><div class="meta mb-2">★ {{$lead->rating ?: '—'}} · {{$lead->total_reviews}} reviews</div>@if($lead->follow_up_date)<div class="meta text-warning-emphasis mb-2"><i class="bi bi-calendar-event"></i> {{$lead->follow_up_date->format('d M Y')}}</div>@endif @if($lead->notes)<p class="meta mb-2">{{\Illuminate\Support\Str::limit($lead->notes,70)}}</p>@endif<div class="card-actions"><a href="{{route('leads.show',$lead)}}" title="Open"><i class="bi bi-eye"></i></a>@if($lead->google_maps_url)<a href="{{$lead->google_maps_url}}" target="_blank" title="Maps"><i class="bi bi-geo-alt"></i></a>@endif @if($lead->whatsapp_message_english)<button type="button" title="Copy message" onclick='navigator.clipboard.writeText(@json($lead->whatsapp_message_english))'><i class="bi bi-whatsapp"></i></button>@endif</div></article>@endforeach</div></section>@endforeach</div>
