@push('scripts')
<script src="https://cdn.jsdelivr.net/npm/sortablejs@1.15.2/Sortable.min.js"></script>
<script>
const token=document.querySelector('meta[name=csrf-token]').content, toast=new bootstrap.Toast('#boardToast');
document.querySelectorAll('.card-list').forEach(list=>new Sortable(list,{group:'leads',animation:160,ghostClass:'sortable-ghost',onEnd:async e=>{
 const card=e.item,status=e.to.dataset.status,old=e.from.dataset.status,oldIndex=e.oldIndex;
 try{const r=await fetch(`/leads/${card.dataset.id}/status`,{method:'PATCH',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':token,'Accept':'application/json'},body:JSON.stringify({status,board_order:e.newIndex})});if(!r.ok)throw Error();document.querySelectorAll('.board-column').forEach(c=>c.querySelector('.column-count').textContent=c.querySelectorAll('.lead-card').length);toast.show();saveOrder()}catch(_){e.from.insertBefore(card,e.from.children[oldIndex]||null);alert('Status update failed. The card was returned to '+old+'.')}}}));
async function saveOrder(){const columns=[...document.querySelectorAll('.card-list')].map(c=>({status:c.dataset.status,leads:[...c.children].map((x,i)=>({id:+x.dataset.id,order:i}))}));await fetch('{{route('leads.board.reorder')}}',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':token,'Accept':'application/json'},body:JSON.stringify({columns})})}
</script>
@endpush
